9	 */
10	
11	#include "self_attention_operation.h"
12	#include <cfloat>
13	#include "atb/utils/config.h"
14	#include "self_attention_fusion_ops_runner.h"
15	#include "self_attention_fusion_bypass_ops_runner.h"
16	#include "self_attention_fusion_bypass_ops_runner_BNSD.h"
17	#include "self_attention_fusion_ops_runner_910a.h"
18	#include "self_attention_fusion_bypass_ops_runner_910a.h"
19	#include "self_attention_fusion_bypass_ops_runner_BNSD_910a.h"
20	#include "self_attention_prefix_encoder_ops_runner.h"
21	#include "atb/utils/tensor_check.h"
22	#include "atb/utils/tensor_util.h"
23	#include "atb/utils/operation_util.h"
24	#include "self_attention_aclnn_runner.h"
25	#include "self_attention_encoder_fusion_ops_runner.h"
26	#include "self_attention_encoder_fusion_ops_runner_910a.h"
27	#include "atb/utils/param_to_json.h"
28	#include "atb/utils/singleton.h"
29	#include "atb/utils/utils_internal.h"
30	#include "atb/operation/atb_operation_ir_cfg.h"
31	#include "atb/operation/op_param_funcs.h"
32	#include "atb/utils/operation_register.h"
33	#include "mki/utils/platform/platform_info.h"
34	
35	namespace atb {
36	static constexpr uint32_t FUSION_IN_TENSOR_NUM = 8;
37	static constexpr uint32_t FUSION_BYPASS_IN_TENSOR_NUM = 6;
38	// query, key, value, blockTables, mask, seqlen, kvSeqLen, slopes
39	static constexpr uint32_t PREFIX_ENCODER_IN_TENSOR_NUM = 8;
40	static constexpr uint32_t PREFIX_128MASK_ENCODER_IN_TENSOR_NUM = 7;
41	static constexpr uint32_t FUSION_OUT_TENSOR_NUM = 1;
42	static constexpr uint32_t NOFUSION_OUT_TENSOR_NUM = 3;
43	static constexpr uint32_t MAX_HEAD_SIZE_MLA_KERNEL = 1024; // mla kernel max
44	static constexpr uint32_t MAX_HEAD_SIZE_MLA = 576; // mla bypass max
45	static constexpr uint32_t MAX_HEAD_SIZE = 256;
46	static const int BATCH_BIT = 0x00001;
47	static const int SLOPES_BIT = 0x00002;
48	static const int MASK_BIT = 0x00004;
49	static const int BYPASS_BIT = 0x00008;
50	static const int SCALE_BIT = 0x00010;
51	static constexpr int64_t COMPRESS_MASK_SIZE = 128;
52	static constexpr int64_t COMPRESS_MASK_SIZE_950 = 2048;
53	static constexpr int64_t LONG_COMPRESS_LEN = 2048;
54	static constexpr int64_t LONG_COMPRESS_NZ_DIM1 = LONG_COMPRESS_LEN / 16;
55	static constexpr int64_t BYTE2_ALIGN = 16;
56	
57	bool ParamCheck950(const infer::SelfAttentionParam &opParam);
58	bool KernelTypeRangeCheck(const infer::SelfAttentionParam &opParam);
59	bool ExpM8v2ParamCheck(const infer::SelfAttentionParam &opParam);
60	bool InputLayoutRangeCheck(const infer::SelfAttentionParam &opParam);
61	
62	template <> Status CreateOperation(const infer::SelfAttentionParam &opParam, Operation **operation)
63	{
64	    if (operation == nullptr) {
65	        return ERROR_INVALID_PARAM;
66	    }
67	    OP_PARAM_RSV_CHECK(opParam);
68	    ATB_LOG(INFO) << OpParamToJson(opParam);
69	    if (!HeadNumCheck(opParam)) {
70	        return ERROR_INVALID_PARAM;
71	    }
72	    if (opParam.kvcacheCfg != atb::infer::SelfAttentionParam::K_BYPASS_V_BYPASS &&
73	        opParam.kvcacheCfg != atb::infer::SelfAttentionParam::K_CACHE_V_CACHE) {
74	        ATB_LOG(ERROR) << "kvcacheCfg is invalid, should be K_CACHE_V_CACHE or K_BYPASS_V_BYPASS";
75	        return ERROR_INVALID_PARAM;
76	    }
77	    if (opParam.quantType == atb::infer::SelfAttentionParam::TYPE_DEQUANT_FUSION) {
78	        ATB_LOG(ERROR) << "quantType can not be TYPE_DEQUANT_FUSION";
79	        return ERROR_INVALID_PARAM;
80	    }
81	    if (Mki::PlatformInfo::Instance().GetPlatformType() == Mki::PlatformType::ASCEND_950) {
82	        Status status = SelfAttentionAclnnRunner::LoadMethod();
83	        if (status != NO_ERROR) {
84	            ATB_LOG(WARN) << "Load Aclnn functions failed!";
85	            return ERROR_CANN_ERROR;
86	        }
87	        if (!ParamCheck950(opParam)) {
88	            return ERROR_INVALID_PARAM;
89	        }
90	    }
91	    bool needQKVQuant = (opParam.quantType == atb::infer::SelfAttentionParam::TYPE_QUANT_QKV_OFFLINE ||
92	                         opParam.quantType == atb::infer::SelfAttentionParam::TYPE_QUANT_QKV_ONLINE);
93	    if (needQKVQuant && (opParam.outDataType != ACL_FLOAT16 && opParam.outDataType != ACL_BF16)) {
94	        ATB_LOG(ERROR) << "outDataType only support ACL_FLOAT16 and ACL_BF16";
95	        return ERROR_INVALID_PARAM;
96	    }
97	    if (needQKVQuant && opParam.calcType != atb::infer::SelfAttentionParam::PA_ENCODER) {
98	        ATB_LOG(ERROR) << "QKVQuant only support when calcType is PA_ENCODER";
99	        return ERROR_INVALID_PARAM;
100	    }
101	    if (opParam.scaleType != infer::SelfAttentionParam::SCALE_TYPE_TOR && needQKVQuant) {
102	        ATB_LOG(ERROR) << "QKVQuant only support when scaleType is SCALE_TYPE_TOR";
103	        return ERROR_INVALID_PARAM;
104	    }
105	    if (opParam.scaleType >= infer::SelfAttentionParam::SCALE_TYPE_MAX ||
106	        opParam.scaleType < infer::SelfAttentionParam::SCALE_TYPE_TOR) {
107	        ATB_LOG(ERROR) << "scaleType should be in the range of its enum value";
108	        return ERROR_INVALID_PARAM;
109	    }
110	    if (opParam.calcType == infer::SelfAttentionParam::PA_ENCODER &&
111	        opParam.kvcacheCfg == atb::infer::SelfAttentionParam::K_BYPASS_V_BYPASS) {
112	        ATB_LOG(ERROR) << "when calcType is PA_ENCODER, kvcacheCfg should not be K_BYPASS_V_BYPASS";
113	        return ERROR_INVALID_PARAM;
114	    }
115	    if (opParam.calcType != infer::SelfAttentionParam::PA_ENCODER &&
116	        opParam.calcType != infer::SelfAttentionParam::PREFIX_ENCODER &&
117	        (opParam.maskType == infer::SelfAttentionParam::MASK_TYPE_ALIBI_COMPRESS ||
118	         opParam.maskType == infer::SelfAttentionParam::MASK_TYPE_ALIBI_COMPRESS_SQRT ||
119	         opParam.maskType == infer::SelfAttentionParam::MASK_TYPE_ALIBI_COMPRESS_LEFT_ALIGN)) {
120	        ATB_LOG(ERROR) << "only PA_ENCODER and PREFIX_ENCODER supports alibi compress mask";
121	        return ERROR_INVALID_PARAM;
122	    }
123	    if (opParam.maskType == infer::SelfAttentionParam::MASK_TYPE_UNDEFINED && opParam.isTriuMask == 1) {
124	        ATB_LOG(ERROR) << "when maskType is MASK_TYPE_UNDEFINED, isTriuMask should not be 1";
125	        return ERROR_INVALID_PARAM;
126	    }
127	    if (!BNSDParamCheck(opParam)) {
128	        return ERROR_INVALID_PARAM;
129	    }
130	    if (!MlaParamCheck(opParam)) {
131	        return ERROR_INVALID_PARAM;
132	    }
133	    if (!SWAParamCheck(opParam)) {
134	        return ERROR_INVALID_PARAM;
135	    }
136	    if (!DeviceParamCheck(opParam)) {
137	        return ERROR_INVALID_PARAM;
138	    }
139	    if (!KernelTypeRangeCheck(opParam)) {
140	        return ERROR_INVALID_PARAM;
141	    }
142	    if (!InputLayoutRangeCheck(opParam)) {
143	        return ERROR_INVALID_PARAM;
144	    }
145	    if (opParam.calcType == infer::SelfAttentionParam::PREFIX_ENCODER && !PrefixEncoderParamCheck(opParam)) {
146	        return ERROR_INVALID_PARAM;
147	    }
148	    if (opParam.kernelType == infer::SelfAttentionParam::KernelType::KERNELTYPE_EXP_M8V2 &&
149	        !ExpM8v2ParamCheck(opParam)) {
150	        return ERROR_INVALID_PARAM;
151	    }
152	    *operation = new (std::nothrow) SelfAttentionOperation(opParam);
153	    if (*operation == nullptr) {
154	        ATB_LOG(ERROR) << "failed to new operation";
155	        return ERROR_OUT_OF_HOST_MEMORY;
156	    }
157	    return NO_ERROR;
158	}
159	
160	bool HeadNumCheck(const infer::SelfAttentionParam &opParam)
161	{
162	    if (opParam.headNum <= 0) {
163	        ATB_LOG(ERROR) << "headNum should be greater than zero!";
164	        return false;
165	    }
166	    if (opParam.kvHeadNum < 0) {
167	        ATB_LOG(ERROR) << "kvHeadNum should be no less than zero!";
168	        return false;
169	    }
170	    if (opParam.kvHeadNum > 0 && opParam.headNum % opParam.kvHeadNum != 0) {
171	        ATB_LOG(ERROR) << "headNum should be divisible by kvHeadNum";
172	        return false;
173	    }
174	    return true;
175	}
176	
177	bool BNSDParamCheck(const infer::SelfAttentionParam &opParam)
178	{
179	    if (opParam.inputLayout == atb::infer::InputLayout::TYPE_BNSD) {
180	        if (opParam.scaleType != atb::infer::SelfAttentionParam::SCALE_TYPE_TOR) {
181	            ATB_LOG(ERROR) << "BNSD feature and scaleType feature cannot coexist";
182	            return false;
183	        }
184	        if (opParam.quantType != atb::infer::SelfAttentionParam::TYPE_QUANT_UNQUANT) {
185	            ATB_LOG(ERROR) << "BNSD feature and quantType feature cannot coexist";
186	            return false;
187	        }
188	        if (opParam.calcType == infer::SelfAttentionParam::PREFIX_ENCODER) {
189	            ATB_LOG(ERROR) << "BNSD feature does not support prefix encoder";
190	            return false;
191	        } else if (opParam.calcType == infer::SelfAttentionParam::PA_ENCODER) {
192	            if (opParam.mlaVHeadSize > 0) {
193	                ATB_LOG(ERROR) << "BNSD feature does not support mla mode";
194	                return false;
195	            }
196	            if (opParam.kernelType == infer::SelfAttentionParam::KERNELTYPE_HIGH_PRECISION) {
197	                ATB_LOG(ERROR) << "PA_ENCODER BNSD does not support KERNELTYPE_HIGH_PRECISION";
198	                return false;
199	            }
200	            bool isExpM8v2 = opParam.kernelType == infer::SelfAttentionParam::KernelType::KERNELTYPE_EXP_M8V2;
201	            if (!GetSingleton<Config>().Is910B()) {
202	                if (GetSingleton<Config>().Is310P()) {
203	                    if (!isExpM8v2) {
204	                        ATB_LOG(ERROR) << "Self Attention PA_ENCODER BNSD only supports kerernelType as "
205	                                          "KERNELTYPE_EXP_M8V2 on Atlas inference products";
206	                        return false;
207	                    }
208	                } else {
209	                    ATB_LOG(ERROR)
210	                        << "Self Attention PA_ENCODER with no KERNELTYPE_EXP_M8V2 BNSD only supports Atlas 800I "
211	                           "A2 inference product";
212	                    return false;
213	                }
214	            }
215	            if (!isExpM8v2 && opParam.maskType != infer::SelfAttentionParam::MASK_TYPE_UNDEFINED) {
216	                ATB_LOG(ERROR) << "when inputLayout is TYPE_BNSD, maskType should be MASK_TYPE_UNDEFINED";
217	                return false;
218	            }
219	        } else {
220	            if (opParam.kvcacheCfg != atb::infer::SelfAttentionParam::K_BYPASS_V_BYPASS) {
221	                ATB_LOG(ERROR) << "when inputLayout is TYPE_BNSD, kvcacheCfg should be K_BYPASS_V_BYPASS";
222	                return false;
223	            }
224	            if (opParam.maskType == infer::SelfAttentionParam::MASK_TYPE_UNDEFINED) {
225	                ATB_LOG(ERROR) << "when inputLayout is TYPE_BNSD, maskType should not be MASK_TYPE_UNDEFINED";
226	                return false;
227	            }
228	        }
229	    }
230	    return true;
231	}
