233	bool DeviceParamCheck(const infer::SelfAttentionParam &opParam)
234	{
235	    if (opParam.maskType == infer::SelfAttentionParam::MASK_TYPE_NORM_COMPRESS &&
236	        GetSingleton<Config>().Is310P()) {
237	        if (opParam.quantType != infer::SelfAttentionParam::TYPE_QUANT_UNDEFINED) {
238	            ATB_LOG(ERROR) << "MASK_TYPE_NORM_COMPRESS does not support quantization";
239	            return false;
240	        }
241	    }
242	    if (!GetSingleton<Config>().Is910B()) {
243	        if (opParam.maskType == infer::SelfAttentionParam::MASK_TYPE_ALIBI_COMPRESS_LEFT_ALIGN) {
244	            ATB_LOG(ERROR) << "MASK_TYPE_ALIBI_COMPRESS_LEFT_ALIGN only support Atlas 800I A2 inference product";
245	            return false;
246	        }
247	        if (opParam.clampType != infer::SelfAttentionParam::ClampType::CLAMP_TYPE_UNDEFINED) {
248	            ATB_LOG(ERROR) << "clamp only support Atlas 800I A2 inference product";
249	            return false;
250	        }
251	        if (opParam.quantType == atb::infer::SelfAttentionParam::TYPE_QUANT_QKV_OFFLINE ||
252	            opParam.quantType == atb::infer::SelfAttentionParam::TYPE_QUANT_QKV_ONLINE) {
253	            ATB_LOG(ERROR) << "QKVQuant only support Atlas 800I A2 inference product";
254	            return false;
255	        }
256	        if (opParam.batchRunStatusEnable) {
257	            ATB_LOG(ERROR) << "Dynamic batch only support Atlas 800I A2 inference product";
258	            return false;
259	        }
260	    }
261	    if (GetSingleton<Config>().Is910A()) {
262	        if (opParam.calcType != infer::SelfAttentionParam::PA_ENCODER) {
263	            ATB_LOG(ERROR) << "Atlas 800 product only supports PA ENCODER";
264	            return false;
265	        }
266	        if (opParam.maskType == infer::SelfAttentionParam::MASK_TYPE_ALIBI_COMPRESS ||
267	            opParam.maskType == infer::SelfAttentionParam::MASK_TYPE_ALIBI_COMPRESS_SQRT ||
268	            opParam.maskType == infer::SelfAttentionParam::MASK_TYPE_ALIBI_COMPRESS_LEFT_ALIGN) {
269	            ATB_LOG(ERROR) << "Atlas 800 product does not support alibi compress mask";
270	            return false;
271	        }
272	        if (opParam.windowSize > 0) {
273	            ATB_LOG(ERROR) << "Atlas 800 product does not support sliding window attention";
274	            return false;
275	        }
276	        if (opParam.scaleType == infer::SelfAttentionParam::SCALE_TYPE_LOGN) {
277	            ATB_LOG(ERROR) << "Atlas 800 product does not support logN";
278	            return false;
279	        }
280	    }
281	    return true;
282	}
