318	bool SWAParamCheck(const infer::SelfAttentionParam &opParam)
319	{
320	    if (opParam.windowSize == 0 &&
321	        (opParam.maskType != infer::SelfAttentionParam::MASK_TYPE_SLIDING_WINDOW_NORM &&
322	         opParam.maskType != infer::SelfAttentionParam::MASK_TYPE_SLIDING_WINDOW_COMPRESS)) { // 不开启swa
