326	        }
327	    } else if (opParam.windowSize > 0 &&
328	               (opParam.maskType == infer::SelfAttentionParam::MASK_TYPE_SLIDING_WINDOW_NORM ||
329	                opParam.maskType == infer::SelfAttentionParam::MASK_TYPE_SLIDING_WINDOW_COMPRESS)) { // 开启swa
330	        if (opParam.maskType == infer::SelfAttentionParam::MASK_TYPE_SLIDING_WINDOW_COMPRESS &&
