332	            ATB_LOG(ERROR) << "maskType should not be MASK_TYPE_SLIDING_WINDOW_COMPRESS for decoder";
333	            return false;
334	        }
335	        if (opParam.batchRunStatusEnable || opParam.kernelType != infer::SelfAttentionParam::KERNELTYPE_DEFAULT ||
336	            opParam.clampType != infer::SelfAttentionParam::CLAMP_TYPE_UNDEFINED ||
337	            opParam.quantType != infer::SelfAttentionParam::TYPE_QUANT_UNQUANT ||
338	            opParam.scaleType != infer::SelfAttentionParam::SCALE_TYPE_TOR || opParam.inputLayout != infer::TYPE_BSND) {
339	            ATB_LOG(ERROR) << "Sliding Window Attention does not support dynamic batch, high precision kernel, "
340	                              "clamp, qkvquant, logN func and BNSD feature";
341	            return false;
342	        }
343	    } else {
344	        ATB_LOG(ERROR) << "windowSize should greater than 0 and maskType should be MASK_TYPE_SLIDING_WINDOW_NORM "
345	                          "or MASK_TYPE_SLIDING_WINDOW_COMPRESS if Sliding Window Attention is used";
346	        return false;
347	    }
348	    return true;
349	}
