351	bool PrefixEncoderParamCheck(const infer::SelfAttentionParam &opParam)
352	{
353	    std::vector<std::pair<bool, const char *>> paramCheckList = {
354	        {GetSingleton<Config>().Is910B(), "PREFIX_ENCODER only support 800I A2/A3 inference product"},
355	        {opParam.quantType == infer::SelfAttentionParam::TYPE_QUANT_UNQUANT,
356	         "PREFIX_ENCODER doesn't support quantification, use default quantType"},
357	        {opParam.outDataType == ACL_DT_UNDEFINED,
358	         "PREFIX_ENCODER doesn't support quantification, use default outDataType"},
359	        {opParam.headNum >= opParam.kvHeadNum, "PREFIX_ENCODER expects headNum >= kvHeadNum"},
360	        {std::abs(opParam.qScale - 1.0f) < FLT_EPSILON, "PREFIX_ENCODER expects qScale to be 1.0f"},
361	        {!opParam.batchRunStatusEnable, "PREFIX_ENCODER doesn't support dynamic batch"},
362	        {opParam.isTriuMask == 1, "PREFIX_ENCODER expects isTriuMask to be 1 for alibi mask"},
363	        {opParam.kernelType == infer::SelfAttentionParam::KERNELTYPE_HIGH_PRECISION,
364	         "PREFIX_ENCODER expects kernelType to be KERNELTYPE_HIGH_PRECISION for alibi mask"},
365	        {opParam.clampType == infer::SelfAttentionParam::CLAMP_TYPE_UNDEFINED, "PREFIX_ENCODER doesn't support clamp"},
366	        {std::abs(opParam.clampMin - 0.0f) < FLT_EPSILON, "PREFIX_ENCODER doesn't support clamp"},
367	        {std::abs(opParam.clampMax - 0.0f) < FLT_EPSILON, "PREFIX_ENCODER doesn't support clamp"},
368	        {opParam.maskType == infer::SelfAttentionParam::MASK_TYPE_ALIBI_COMPRESS ||
369	             opParam.maskType == infer::SelfAttentionParam::MASK_TYPE_ALIBI_COMPRESS_SQRT ||
370	             opParam.maskType == infer::SelfAttentionParam::MASK_TYPE_NORM_COMPRESS ||
371	             opParam.maskType == infer::SelfAttentionParam::MASK_TYPE_CAUSAL_MASK,
372	         "PREFIX_ENCODER only supports alibi compress mask, norm compress mask and alibi compress sqrt mask"},
373	        {opParam.kvcacheCfg == atb::infer::SelfAttentionParam::K_CACHE_V_CACHE,
374	         "PREFIX_ENCODER doesn't support key value bypass"},
375	        {opParam.scaleType == infer::SelfAttentionParam::SCALE_TYPE_TOR, "PREFIX_ENCODER doesn't support logN scale"},
376	        {opParam.inputLayout == infer::TYPE_BSND, "PREFIX_ENCODER only supports when inputLayout is TYPE_BSND"},
377	        {opParam.cacheType == atb::infer::SelfAttentionParam::CACHE_TYPE_NORM,
378	         "PREFIX_ENCODER only supports normal cache type"},
379	        {opParam.mlaVHeadSize == 0, "PREFIX_ENCODER doesn't support mla"},
380	        {opParam.windowSize == 0, "PREFIX_ENCODER doesn't support swa"}};
381	    for (const std::pair<bool, const char *> &paramCheckItem : paramCheckList) {
382	        if (!paramCheckItem.first) {
383	            ATB_LOG(ERROR) << paramCheckItem.second;
384	            return false;
385	        }
386	    }
387	    return true;
388	}
