535	    if (opParam.scaleType != infer::SelfAttentionParam::ScaleType::SCALE_TYPE_TOR) {
536	        ATB_LOG(ERROR) << "Self attention with KERNELTYPE_EXP_M8V2 only supports SCALE_TYPE_TOR.";
