569	SelfAttentionOperation::SelfAttentionOperation(const infer::SelfAttentionParam &param)
570	    : OperationBase("SelfAttentionOperation"), param_(param)
571	{
572	    if (param_.maskType == infer::SelfAttentionParam::MASK_TYPE_NORM_COMPRESS &&
573	        GetSingleton<Config>().Is310P()) {
574	        param_.isTriuMask = 1;
575	    }
576	    isMla_ = param_.mlaVHeadSize > 0;
577	    hasMask_ = (param_.maskType != infer::SelfAttentionParam::MASK_TYPE_UNDEFINED
578	                && param_.maskType != infer::SelfAttentionParam::MASK_TYPE_CAUSAL_MASK) &&
579	               !(param_.calcType == infer::SelfAttentionParam::DECODER &&
580	                 param_.maskType == infer::SelfAttentionParam::MASK_TYPE_SLIDING_WINDOW_NORM);
581	    kvHeadNum_ = (param_.kvHeadNum > 0) ? param_.kvHeadNum : param_.headNum;
582	    if (param_.calcType == infer::SelfAttentionParam::PA_ENCODER) {
583	        kcacheId_ = 1;
584	        maskId_ = 3;                       // 3: mask
585	        tokenOffsetId_ = hasMask_ ? 4 : 3; // tokenoffset 4: with mask 3: no mask
586	        if (isMla_) {
587	            tokenOffsetId_--;
588	            maskId_--;
589	        }
590	        hasSlopes_ = param_.maskType == infer::SelfAttentionParam::MASK_TYPE_ALIBI_COMPRESS ||
591	                     param_.maskType == infer::SelfAttentionParam::MASK_TYPE_ALIBI_COMPRESS_SQRT ||
592	                     param_.maskType == infer::SelfAttentionParam::MASK_TYPE_ALIBI_COMPRESS_LEFT_ALIGN;
593	        InitPaEncoderOpIni();
594	    } else if (param_.calcType == atb::infer::SelfAttentionParam::PREFIX_ENCODER) {
595	        maskId_ = 4; // 4: mask: query, key, value, blockTables, mask, qSeqLen, kvSeqLen, slopes
596	        kcacheId_ = 1;
597	        hasSlopes_ = true;
598	        if (param_.maskType == infer::SelfAttentionParam::MASK_TYPE_NORM_COMPRESS) {
599	            hasSlopes_ = false;
600	            operationIr_ = GetSingleton<AtbOperationIrCfg>().GetOperationIr("SelfAttentionOperationPrefixEncoder");
601	        } else if (param_.maskType == infer::SelfAttentionParam::MASK_TYPE_CAUSAL_MASK) {
602	            hasSlopes_ = false;
603	            operationIr_ =
604	                GetSingleton<AtbOperationIrCfg>().GetOperationIr("SelfAttentionOperationPrefixEncoderCausalMask");
605	        } else {
606	            operationIr_ =
607	                GetSingleton<AtbOperationIrCfg>().GetOperationIr("SelfAttentionOperationPrefixEncoderSlopes");
608	        }
609	    } else {
610	        kcacheId_ = 3;                     // 3: kcache
611	        maskId_ = 5;                       // 5: mask
612	        tokenOffsetId_ = hasMask_ ? 6 : 5; // tokenoffset 6: with mask 5: no mask
613	        if (param_.kvcacheCfg == atb::infer::SelfAttentionParam::K_BYPASS_V_BYPASS) {
614	            maskId_ -= 2;        // 2: key, value
615	            tokenOffsetId_ -= 2; // 2: key, value
616	            kcacheId_ -= 2;      // 2: key, value
617	        }
618	        InitFaOpIni();
619	    }
620	}
