622	uint32_t SelfAttentionOperation::Bools2Int(bool hasScale, bool hasKV, bool hasMask, bool hasSlopes, bool hasBatch) const
623	{
624	    uint32_t ret = 0;
625	    ret = hasScale ? (ret | SCALE_BIT) : ret;
626	    ret = !hasKV ? (ret | BYPASS_BIT) : ret;
627	    ret = hasMask ? (ret | MASK_BIT) : ret;
628	    ret = hasSlopes ? (ret | SLOPES_BIT) : ret;
629	    ret = hasBatch ? (ret | BATCH_BIT) : ret;
630	    return ret;
631	}
