741	uint32_t SelfAttentionOperation::GetInputNum() const
742	{
743	    bool hasKV = (param_.kvcacheCfg != atb::infer::SelfAttentionParam::K_BYPASS_V_BYPASS);
744	    uint32_t inputNumBase = hasKV ? FUSION_IN_TENSOR_NUM : FUSION_BYPASS_IN_TENSOR_NUM; // 6或8
745	    if (param_.calcType == infer::SelfAttentionParam::PA_ENCODER) {
746	        uint32_t inputNumBasePa =
747	            (param_.maskType == infer::SelfAttentionParam::MASK_TYPE_UNDEFINED ? 4 : // 4: no mask
748	                 (param_.maskType == infer::SelfAttentionParam::MASK_TYPE_ALIBI_COMPRESS ||
749	                  param_.maskType == infer::SelfAttentionParam::MASK_TYPE_ALIBI_COMPRESS_SQRT ||
750	                  // 6: mask and slopes, 5: mask
751	                  param_.maskType == infer::SelfAttentionParam::MASK_TYPE_ALIBI_COMPRESS_LEFT_ALIGN) ?
752	                                                                                 6 :
753	                                                                                 5) +
754	            (param_.scaleType == infer::SelfAttentionParam::SCALE_TYPE_LOGN ? 1 : 0);
755	        bool needQKVOnlineQuant = (param_.quantType == atb::infer::SelfAttentionParam::TYPE_QUANT_QKV_ONLINE);
756	        bool needQKVOfflineQuant = (param_.quantType == atb::infer::SelfAttentionParam::TYPE_QUANT_QKV_OFFLINE);
757	        if (needQKVOnlineQuant) {
758	            inputNumBasePa += 4; // 4: qkDescale、qkOffset、vpvDescale、vpvOffset
759	        }
760	        if (needQKVOfflineQuant) {
761	            inputNumBasePa += 5; // 5: qkDescale、qkOffset、vpvDescale、vpvOffset、pScale
762	        }
763	        if (isMla_) {
764	            inputNumBasePa--; // 没有value
765	        }
766	        return inputNumBasePa;
767	    } else if (param_.calcType == infer::SelfAttentionParam::PREFIX_ENCODER) {
768	        if (param_.maskType == infer::SelfAttentionParam::MASK_TYPE_NORM_COMPRESS) {
769	            return PREFIX_128MASK_ENCODER_IN_TENSOR_NUM;
770	        } else if (param_.maskType == infer::SelfAttentionParam::MASK_TYPE_CAUSAL_MASK) {
771	            return FUSION_BYPASS_IN_TENSOR_NUM;
772	        } else {
773	            return PREFIX_ENCODER_IN_TENSOR_NUM;
774	        }
775	    }
776	    if (param_.batchRunStatusEnable) {
777	        inputNumBase += 1;
778	    }
779	    if (param_.maskType != infer::SelfAttentionParam::MASK_TYPE_UNDEFINED &&
780	        !(param_.calcType == infer::SelfAttentionParam::DECODER &&
781	          param_.maskType == infer::SelfAttentionParam::MASK_TYPE_SLIDING_WINDOW_NORM)) {
782	        inputNumBase += 1; // need mask
783	    }
784	    if (param_.maskType == infer::SelfAttentionParam::MASK_TYPE_ALIBI_COMPRESS ||
785	        param_.maskType == infer::SelfAttentionParam::MASK_TYPE_ALIBI_COMPRESS_SQRT) {
786	        inputNumBase += 1; // need slopes
787	    }
788	    if (param_.scaleType == infer::SelfAttentionParam::SCALE_TYPE_LOGN) {
789	        inputNumBase += 1; // need logn scale
790	    }
791	    return inputNumBase;
792	}
