803	Status SelfAttentionOperation::BypassInferShapeImpl910B(const SVector<TensorDesc> &inTensorDescs,
804	                                                        SVector<TensorDesc> &outTensorDescs) const
805	{
806	    outTensorDescs.at(0) = inTensorDescs.at(0);
807	    int64_t vHeadSize = 0;
808	    // when layout is BNSD, vCache shape: [B,N,S,D]
809	    uint32_t headSizePos = inTensorDescs.at(2).shape.dimNum - 1; // 2: valueTensor
810	    vHeadSize = inTensorDescs.at(2).shape.dims[headSizePos];     // 2: valueTensor
811	    if (param_.inputLayout == atb::infer::InputLayout::TYPE_BSND) {
812	        // vCache: [layerNum, B, S, ND]
813	        if (vHeadSize % kvHeadNum_ != 0) {
814	            ATB_LOG(ERROR) << GetLogPrefix() << "expect intensor2, vCache's hiddenSize(dim3) to be multiple of kvhead "
815	                           << kvHeadNum_ << ", but got " << vHeadSize;
816	            return ERROR_INVALID_TENSOR_DIM;
817	        }
818	        vHeadSize /= kvHeadNum_;
819	    }
820	    if (inTensorDescs.at(0).shape.dimNum == 4) { // 4: 总维度数量 [B,S,N,D]/[B,N,S,D]
821	        outTensorDescs.at(0).shape.dimNum = 3;   // 3: 表示输出维度
822	        outTensorDescs.at(0).shape.dims[0] = inTensorDescs.at(0).shape.dims[0];
823	        outTensorDescs.at(0).shape.dims[1] = inTensorDescs.at(0).shape.dims[1];
824	        outTensorDescs.at(0).shape.dims[2] = param_.headNum * vHeadSize; // 2: valueCache, 3: hiddenSize
825	    } else { // q shape: [BS,ND]
826	        outTensorDescs.at(0).shape.dims[1] = param_.headNum * vHeadSize;
827	    }
828	    return NO_ERROR;
829	}
830	
831	Status SelfAttentionOperation::InferShapeImpl910B(const SVector<TensorDesc> &inTensorDescs,
832	                                                  SVector<TensorDesc> &outTensorDescs) const
833	{
834	    if (param_.inputLayout == atb::infer::InputLayout::TYPE_BNSD) {
835	        outTensorDescs.at(0) = inTensorDescs.at(0);
836	        return NO_ERROR;
837	    }
838	    if (param_.kvcacheCfg == atb::infer::SelfAttentionParam::K_BYPASS_V_BYPASS) {
839	        return BypassInferShapeImpl910B(inTensorDescs, outTensorDescs);
840	    }
841	    if (param_.calcType == atb::infer::SelfAttentionParam::PREFIX_ENCODER) {
842	        outTensorDescs.at(0) = inTensorDescs.at(0);
843	        return NO_ERROR;
844	    }
845	    if (inTensorDescs.at(0).shape.dimNum == 4) { // 4: 总维度数量
846	        outTensorDescs.at(0).dtype = inTensorDescs.at(0).dtype;
847	        outTensorDescs.at(0).format = inTensorDescs.at(0).format;
848	        outTensorDescs.at(0).shape.dimNum = 3; // 3: 表示输出维度
849	        outTensorDescs.at(0).shape.dims[0] = inTensorDescs.at(0).shape.dims[0];
850	        outTensorDescs.at(0).shape.dims[1] = inTensorDescs.at(0).shape.dims[1]; // batch == 1
851	        int64_t vHiddenSize =
852	            isMla_ ? param_.mlaVHeadSize : inTensorDescs.at(2).shape.dims[3]; // 2, 3: 设置第三维度的大小
853	        outTensorDescs.at(0).shape.dims[2] =                                  // 2: 设置第二维度的大小
854	            inTensorDescs.at(0).shape.dims[2] * vHiddenSize;                  // 2: 设置第三维度的大小
855	    } else if (inTensorDescs.at(0).shape.dimNum == 2) { // outTensor需要合轴 2: [nTokens, hiddenSize]
856	        outTensorDescs.at(0) = inTensorDescs.at(0);
857	        int32_t qHeadNum = param_.headNum;
858	        int64_t vHiddenSize = 0;
859	        if (isMla_) {
860	            vHiddenSize = param_.mlaVHeadSize;
861	        } else if (inTensorDescs.at(2).shape.dimNum == 2) { // 2: valueTensor 2: [nTokens, hiddenSize]
862	            // kvHeadNum_ is checked to be > 0 in CreateOperation()
863	            vHiddenSize = inTensorDescs.at(2).shape.dims[1] / kvHeadNum_; // 2: valueTensor
864	        } else {
865	            uint32_t hiddenSizePos = inTensorDescs.at(2).shape.dimNum - 1; // 2: valueTensor
866	            vHiddenSize = inTensorDescs.at(2).shape.dims[hiddenSizePos];   // 2: valueTensor
867	        }
868	        outTensorDescs.at(0).shape.dims[1] = qHeadNum * vHiddenSize;
869	    } else { // pa encoder q: [nTokens, head_num, head_size]
870	        outTensorDescs.at(0) = inTensorDescs.at(0);
871	        outTensorDescs.at(0).shape.dims[2] = isMla_ ? param_.mlaVHeadSize :         // 2: head_size
872	                                                      inTensorDescs.at(2).shape.dims[2]; // 2: value
873	    }
874	    if (param_.quantType == atb::infer::SelfAttentionParam::TYPE_QUANT_QKV_OFFLINE ||
875	        param_.quantType == atb::infer::SelfAttentionParam::TYPE_QUANT_QKV_ONLINE) {
876	        outTensorDescs.at(0).dtype = param_.outDataType;
877	    }
878	    return NO_ERROR;
879	}
