904	Status SelfAttentionOperation::DtypeCheck(const SVector<TensorDesc> &inTensorDescs) const
905	{
906	    aclFormat targetFormat = ACL_FORMAT_ND;
907	    if (!GetSingleton<Config>().Is910B() &&
908	        Mki::PlatformInfo::Instance().GetPlatformType() != Mki::PlatformType::ASCEND_950) {
909	        targetFormat = ACL_FORMAT_FRACTAL_NZ;
910	    }
911	    if (param_.calcType != infer::SelfAttentionParam::PA_ENCODER) {
912	        if (inTensorDescs.at(kcacheId_).format != targetFormat ||
913	            inTensorDescs.at(kcacheId_ + 1).format != targetFormat) { // +1 : vcache
914	            ATB_LOG(ERROR) << "kvcache dtype should be ACL_FORMAT_ND on 800I A2 inference product, "
915	                           << "and ACL_FORMAT_FRACTAL_NZ on Atlas 800 product "
916	                           << "and Atlas inference products (with Ascend 310P AI Processors)";
917	            return ERROR_INVALID_TENSOR_DTYPE;
918	        }
919	    }
920	    return NO_ERROR;
921	}
