923	Status SelfAttentionOperation::InferShapeCheckImpl(const SVector<TensorDesc> &inTensorDescs) const
924	{
925	    Status st = NO_ERROR;
926	    st = DtypeCheck(inTensorDescs);
927	    if (st != NO_ERROR) {
928	        return st;
929	    }
930	    st = InferLogNCheck(inTensorDescs);
931	    if (st != NO_ERROR) {
932	        return st;
933	    }
934	    bool needQKVQuant = (param_.quantType == atb::infer::SelfAttentionParam::TYPE_QUANT_QKV_OFFLINE ||
935	                         param_.quantType == atb::infer::SelfAttentionParam::TYPE_QUANT_QKV_ONLINE);
936	    if (needQKVQuant) {
937	        st = InferQKVQuantDimCheck(inTensorDescs);
938	        if (st != NO_ERROR) {
939	            return st;
940	        }
941	    }
942	    if (param_.inputLayout == atb::infer::InputLayout::TYPE_BNSD) {
943	        if (param_.calcType == infer::SelfAttentionParam::PA_ENCODER) {
944	            st = InferShapePADimCheckBNSD(inTensorDescs);
945	        } else {
946	            st = GetSingleton<Config>().Is910B() ? InferShapeBypassDimCheckBNSD910B(inTensorDescs) :
947	                                                   InferShapeBypassDimCheckBNSD310P(inTensorDescs);
948	        }
949	        if (st != NO_ERROR) {
950	            return st;
951	        }
952	    } else { // BSND
953	        st = (GetSingleton<Config>().Is910B() || 
954	            Mki::PlatformInfo::Instance().GetPlatformType() == Mki::PlatformType::ASCEND_950) ?
955	            HeadSizeDimCheck910B(inTensorDescs) : HeadSizeDimCheck310P(inTensorDescs);
956	        if (st != NO_ERROR) {
957	            return st;
958	        }
959	        if (param_.windowSize > 0) {
960	            st = SWAMaskDimCheck(inTensorDescs);
961	            if (st != NO_ERROR) {
962	                return st;
963	            }
964	        }
965	        switch (param_.calcType) {
966	            case infer::SelfAttentionParam::PA_ENCODER:
967	                st = InferShapePADimCheck(inTensorDescs);
968	                break;
969	            case infer::SelfAttentionParam::PREFIX_ENCODER:
970	                st = InferShapePrefixDimCheck910B(inTensorDescs);
971	                break;
972	            default:
973	                st = InferShapeDimCheck(inTensorDescs);
974	        }
975	        if (st != NO_ERROR) {
976	            return st;
977	        }
978	    }
979	    return NO_ERROR;
980	}
