982	Status SelfAttentionOperation::SetupCheckImpl(const SVector<Tensor> &inTensors, const SVector<Tensor> &outTensors) const
983	{
984	    Status st = NO_ERROR;
985	    SVector<TensorDesc> inTensorDescs = {};
986	    OperationUtil::InTensorsToInTensorDescs(inTensors, inTensorDescs);
987	    st = DtypeCheck(inTensorDescs);
988	    if (st != NO_ERROR) {
989	        return st;
990	    }
991	    if (param_.inputLayout == atb::infer::InputLayout::TYPE_BNSD) {
992	        if (param_.calcType == infer::SelfAttentionParam::PA_ENCODER) {
993	            st = InferShapePADimCheckBNSD(inTensorDescs);
994	        } else {
995	            st = GetSingleton<Config>().Is910B() ? InferShapeBypassDimCheckBNSD910B(inTensorDescs) :
996	                                                   InferShapeBypassDimCheckBNSD310P(inTensorDescs);
997	        }
998	    } else {
999	        switch (param_.calcType) {
1000	            case infer::SelfAttentionParam::PA_ENCODER:
1001	                st = InferShapePADimCheck(inTensorDescs);
1002	                break;
1003	            case infer::SelfAttentionParam::PREFIX_ENCODER:
1004	                st = InferShapePrefixDimCheck910B(inTensorDescs);
1005	                break;
1006	            default:
1007	                st = InferShapeDimCheck(inTensorDescs);
1008	        }
1009	    }
1010	    if (st != NO_ERROR) {
1011	        return st;
1012	    }
1013	    if (param_.inputLayout == atb::infer::InputLayout::TYPE_BSND) {
1014	        st = (GetSingleton<Config>().Is910B() || 
1015	            Mki::PlatformInfo::Instance().GetPlatformType() == Mki::PlatformType::ASCEND_950) ?
1016	            HeadSizeDimCheck910B(inTensorDescs) : HeadSizeDimCheck310P(inTensorDescs);
1017	        if (st != NO_ERROR) {
1018	            return st;
1019	        }
1020	        st = SetupOutTensorCheck(inTensorDescs, outTensors);
1021	        if (st != NO_ERROR) {
1022	            return st;
1023	        }
1024	    }
1025	    if (param_.windowSize > 0) {
1026	        st = SWAMaskDimCheck(inTensorDescs);
1027	        if (st != NO_ERROR) {
1028	            return st;
1029	        }
1030	    }
1031	    if (Mki::PlatformInfo::Instance().GetPlatformType() == Mki::PlatformType::ASCEND_950 &&
1032	        !SetupTensorDimCheckImpl95(inTensors, outTensors)) {
1033	        return ERROR_INVALID_TENSOR_DIM;
1034	    }
1035	    return NO_ERROR;
1036	}
