1038	bool SelfAttentionOperation::SetupTensorDimCheckImpl95(const SVector<Tensor> &inTensors, const SVector<Tensor> &outTensors) const
1039	{
1040	    int32_t nTokens = CalSeqLenSum(inTensors, inTensors.size() - 1);
1041	    auto headNum = inTensors[0].desc.shape.dims[1];
1042	    auto vHeadSize = inTensors[2].desc.shape.dims[2];
1043	    // Q/K/V check
1044	    if (inTensors[0].desc.shape.dims[0] != nTokens &&
1045	        inTensors[1].desc.shape.dims[0] != nTokens &&
1046	        inTensors[2].desc.shape.dims[0] != nTokens) {
1047	        ATB_LOG(ERROR) << GetLogPrefix() << "The nTokens does not match, please check.";
1048	        return false;
1049	    }
1050	    // output check
1051	    if (outTensors[0].desc.shape.dims[0] != nTokens) {
1052	        ATB_LOG(ERROR) << GetLogPrefix() << "The nTokens does not match, please check.";
1053	        return false;
1054	    }
1055	    if (outTensors[0].desc.shape.dims[1] != headNum) {
1056	        ATB_LOG(ERROR) << GetLogPrefix() << "The headNum does not match, please check.";
1057	        return false;
1058	    }
1059	    if (outTensors[0].desc.shape.dims[2] != vHeadSize) {
1060	        ATB_LOG(ERROR) << GetLogPrefix() << "The vHeadSize does not match, please check.";
1061	        return false;
1062	    }
1063	    return true;
1064	}
