1066	int32_t SelfAttentionOperation::CalSeqLenSum(const SVector<Tensor> &inTensors, const size_t seqLenTensorId) const
1067	{
1068	    const Tensor &seqLenTensor = inTensors.at(seqLenTensorId);
1069	    if (!seqLenTensor.hostData) {
1070	#ifdef _DEBUG
1071	        ATB_LOG(ERROR) << GetLogPrefix() << "tensor.hostData is null, seqLenTensor.hostData:" << seqLenTensor.hostData;
1072	#else
1073	        ATB_LOG(ERROR) << GetLogPrefix() << "tensor.hostData is null";
1074	#endif
1075	        return false;
1076	    }
1077	
1078	    // dims = [batch]
1079	    uint32_t batch = seqLenTensor.desc.shape.dims[0];
1080	
1081	    int32_t seqLenSum = 0;
1082	    int32_t *seqLenTensorHostData = (int32_t *)seqLenTensor.hostData;
1083	    for (size_t i = 0; i < batch; ++i) {
1084	        seqLenSum += seqLenTensorHostData[i];
1085	    }
1086	    ATB_LOG(INFO) << GetLogPrefix() << "nTokens:" << seqLenSum;
1087	    return seqLenSum;
1088	}
