1161	Status SelfAttentionOperation::InferShapeDimCheck(const SVector<TensorDesc> &inTensorDescs) const
1162	{
1163	    Status st = InferShapeDimNumCheck(inTensorDescs);
1164	    if (st != NO_ERROR) {
1165	        return st;
1166	    }
1167	    if (param_.kvcacheCfg != atb::infer::SelfAttentionParam::K_BYPASS_V_BYPASS) {
1168	        st = InferShapeHiddenSizeCheck(inTensorDescs);
1169	        if (st != NO_ERROR) {
1170	            return st;
1171	        }
1172	    }
1173	    // nd格式kvcache shape除最后一维外相同，nz格式kvcache shape相同
1174	    int64_t kvCacheRange = (GetSingleton<Config>().Is910B() ||
1175	    Mki::PlatformInfo::Instance().GetPlatformType() == Mki::PlatformType::ASCEND_950) ?
1176	    inTensorDescs.at(kcacheId_).shape.dimNum - 1 : 5; // 5: nz kvcache dimNum
1177	    for (int64_t i = 0; i < kvCacheRange; i++) {
1178	        if (inTensorDescs.at(kcacheId_).shape.dims[i] != inTensorDescs.at(kcacheId_ + 1).shape.dims[i]) {
1179	            ATB_LOG(ERROR) << "invalid kvcache shape";
1180	            return ERROR_INVALID_TENSOR_DIM;
1181	        }
1182	    }
1183	    int64_t batchPos = param_.batchRunStatusEnable ? 0 : 1;
1184	    int64_t batch = inTensorDescs.at(kcacheId_).shape.dims[batchPos];  // 3: cackeK 1: 1st dim
1185	    if (batch != inTensorDescs.at(tokenOffsetId_).shape.dims[0] ||     // tokenOffset
1186	        batch != inTensorDescs.at(tokenOffsetId_ + 1).shape.dims[0] || // tokenOffsetId_ + 1: seqLen
1187	        (param_.batchRunStatusEnable &&
1188	         batch != inTensorDescs.at(tokenOffsetId_ + 3).shape.dims[0])) { // 3: batchStatus
1189	        ATB_LOG(ERROR) << "batch should be same";
1190	        return ERROR_INVALID_TENSOR_DIM;
1191	    }
1192	    return NO_ERROR;
1193	}
