1195	Status SelfAttentionOperation::InferShapePADimCheck(const SVector<TensorDesc> &inTensorDescs) const
1196	{
1197	    Status st = InferShapePADimNumCheck(inTensorDescs);
1198	    if (st != NO_ERROR) {
1199	        return st;
1200	    }
1201	    if (Mki::PlatformInfo::Instance().GetPlatformType() == Mki::PlatformType::ASCEND_950 &&
1202	        !InferShapeInTensorDimCheckImpl(inTensorDescs)) {
1203	        return ERROR_INVALID_TENSOR_DIM;
1204	    }
1205	    if (!isMla_) {
1206	        for (size_t i = 0; i < inTensorDescs.at(kcacheId_).shape.dimNum - 1; i++) { // kvcache shape除最后一维外相同
1207	            if (inTensorDescs.at(kcacheId_).shape.dims[i] != inTensorDescs.at(kcacheId_ + 1).shape.dims[i]) {
1208	                ATB_LOG(ERROR) << "invalid kvcache shape";
1209	                return ERROR_INVALID_TENSOR_DIM;
1210	            }
1211	        }
1212	    }
1213	    if (hasMask_) {
1214	        if (GetSingleton<Config>().Is910B() ||
1215	            Mki::PlatformInfo::Instance().GetPlatformType() == Mki::PlatformType::ASCEND_950) {
1216	            st = PAMaskDimCheck(inTensorDescs);
1217	        } else if (param_.kernelType == infer::SelfAttentionParam::KernelType::KERNELTYPE_EXP_M8V2) {
1218	            // m8v2 supports nd and nz mask
1219	            if (param_.maskType == infer::SelfAttentionParam::MaskType::MASK_TYPE_NORM_COMPRESS ||
1220	                param_.maskType == infer::SelfAttentionParam::MASK_TYPE_NORM) {
1221	                st = NormMaskDimCheck(inTensorDescs);
1222	            }
1223	        } else {
1224	            st = PAMaskDimCheckNz(inTensorDescs);
1225	        }
1226	        if (st != NO_ERROR) {
1227	            return st;
1228	        }
1229	    }
1230	    if (hasSlopes_ && inTensorDescs.at(tokenOffsetId_ + 1).shape.dims[0] != param_.headNum) {
1231	        ATB_LOG(ERROR) << "shape of slopes should be the same as headNum";
1232	        return ERROR_INVALID_TENSOR_DIM;
1233	    }
1234	    if (inTensorDescs.at(tokenOffsetId_).shape.dimNum == 2 &&  // 2: dimNum [2, batch]
1235	        inTensorDescs.at(tokenOffsetId_).shape.dims[0] != 2) { // 2: [2, batch]
1236	        ATB_LOG(ERROR) << "shape of seqlen should be [batch] or [2, batch]";
1237	        return ERROR_INVALID_TENSOR_DIM;
1238	    }
1239	    return NO_ERROR;
1240	}
