1242	bool SelfAttentionOperation::InferShapeInTensorDimCheckImpl(
1243	    const SVector<TensorDesc> &inTensorDesc) const
1244	{
1245	    auto headNum = inTensorDesc[0].shape.dims[1];
1246	    auto headSize = inTensorDesc[0].shape.dims[2];
1247	    auto kvHeadNum = inTensorDesc[1].shape.dims[1];
1248	    auto vHeadSize = inTensorDesc[2].shape.dims[2];
1249	    // Q/K/V check
1250	    if (headSize != inTensorDesc[1].shape.dims[2]) {
1251	        ATB_LOG(ERROR) << GetLogPrefix() << "The headSize does not match, please check.";
1252	        return false;
1253	    }
1254	    if (headSize != vHeadSize) {
1255	        ATB_LOG(INFO) << "headSizes is different from vHeadSize. The MLA function is enabled.";
1256	        if (headSize != 192 || vHeadSize != 128) {
1257	            ATB_LOG(ERROR) << GetLogPrefix()
1258	                           << "When the MLA function is active, headSize should be 192, and vHeadSize should be 128. "
1259	                           << "However, the actual headSize is " << headSize << ", and vHeadSize is " << vHeadSize
1260	                           << ".";
1261	            return false;
1262	        }
1263	    }
1264	    if (kvHeadNum != inTensorDesc[2].shape.dims[1]) {
1265	        ATB_LOG(ERROR) << GetLogPrefix() << "The kvHeadNum does not match, please check.";
1266	        return false;
1267	    }
1268	    if (headNum != param_.headNum) {
1269	        ATB_LOG(ERROR) << GetLogPrefix() << "The headNum does not match, please check.";
1270	        return false;
1271	    }
1272	    auto paramKVHeadNum = param_.kvHeadNum == 0 ? param_.headNum : param_.kvHeadNum;
1273	    if (kvHeadNum != paramKVHeadNum) {
1274	        ATB_LOG(ERROR) << GetLogPrefix() << "The kvHeadNum does not match, please check.";
1275	        return false;
1276	    }
1277	    if (param_.maskType == atb::infer::SelfAttentionParam::MASK_TYPE_NORM ||
1278	        param_.maskType == atb::infer::SelfAttentionParam::MASK_TYPE_NORM_COMPRESS) {
1279	        if (inTensorDesc[3].shape.dimNum == 3 && inTensorDesc[3].shape.dims[0] != inTensorDesc[4].shape.dims[0]) {
1280	            ATB_LOG(ERROR) << GetLogPrefix() << "The batch does not match, please check.";
1281	            return false;
1282	        }
1283	    }
1284	    return true;
1285	}
