1287	Status SelfAttentionOperation::InferShapePADimCheckBNSD(const SVector<TensorDesc> &inTensorDescs) const
1288	{
1289	    Status st = InferShapePADimNumCheckBNSD(inTensorDescs);
1290	    if (st != NO_ERROR) {
1291	        return st;
1292	    }
1293	    if (!TensorUtil::TensorDescEqual(inTensorDescs.at(kcacheId_), inTensorDescs.at(kcacheId_ + 1))) {
1294	        ATB_LOG(ERROR) << GetLogPrefix() << "shape of key and value should be same";
1295	        return ERROR_INVALID_TENSOR_DIM;
1296	    }
1297	    uint32_t batch = inTensorDescs.at(tokenOffsetId_).shape.dims[0];
1298	    if (inTensorDescs.at(tokenOffsetId_).shape.dimNum == 2) { // 2: [2, batch]
1299	        batch = inTensorDescs.at(tokenOffsetId_).shape.dims[1];
1300	        if (inTensorDescs.at(tokenOffsetId_).shape.dims[0] != 2) { // 2: [2, batch]
1301	            ATB_LOG(ERROR) << GetLogPrefix() << "shape of seqlen should be [batch] or [2, batch]";
1302	            return ERROR_INVALID_TENSOR_DIM;
1303	        }
1304	    }
1305	    if (batch != inTensorDescs.at(0).shape.dims[0]) {
1306	        ATB_LOG(ERROR) << GetLogPrefix() << "batch of seqlen, query should be same";
1307	        return ERROR_INVALID_TENSOR_DIM;
1308	    }
1309	    if (batch != inTensorDescs.at(kcacheId_).shape.dims[0]) {
1310	        ATB_LOG(ERROR) << GetLogPrefix() << "batch of seqlen, key and vlaue should be same";
1311	        return ERROR_INVALID_TENSOR_DIM;
1312	    }
1313	    if (inTensorDescs.at(0).shape.dims[1] != param_.headNum) {
1314	        ATB_LOG(ERROR) << GetLogPrefix() << "2nd dim of query should be same as param headNum when inputLayout is TYPE_BNSD";
1315	        return ERROR_INVALID_TENSOR_DIM;
1316	    }
1317	    if (inTensorDescs.at(1).shape.dims[1] != kvHeadNum_) {
1318	        ATB_LOG(ERROR) << GetLogPrefix() << "2nd dim of key should be same as kvHeadNum when inputLayout is TYPE_BNSD";
1319	        return ERROR_INVALID_TENSOR_DIM;
1320	    }
1321	    if (inTensorDescs.at(0).shape.dims[3] != inTensorDescs.at(kcacheId_).shape.dims[3]) { // 3: headSize
1322	        ATB_LOG(ERROR) << GetLogPrefix() << "headSize of key and query should be same";
1323	        return ERROR_INVALID_TENSOR_DIM;
1324	    }
1325	    if (inTensorDescs.at(0).shape.dims[3] > MAX_HEAD_SIZE) { // 3: headSize
1326	        ATB_LOG(ERROR) << GetLogPrefix() << "headSize should be no greater than 256 when inputLayout is TYPE_BNSD";
1327	        return ERROR_INVALID_TENSOR_DIM;
1328	    }
1329	    return NO_ERROR;
1330	}
1331	
1332	Status SelfAttentionOperation::NormMaskDimCheck(const SVector<TensorDesc> &inTensorDescs) const
1333	{
1334	    aclFormat maskFormat = inTensorDescs.at(maskId_).format;
1335	    int64_t actualMaskDim = inTensorDescs.at(maskId_).shape.dimNum;
1336	    if (param_.maskType == infer::SelfAttentionParam::MaskType::MASK_TYPE_NORM_COMPRESS) {
1337	        int64_t maskDim = 2;
1338	        if (maskFormat == ACL_FORMAT_FRACTAL_NZ) {
1339	            maskDim = 4;
1340	            if (actualMaskDim != maskDim) {
1341	                ATB_LOG(ERROR) << GetLogPrefix() << "invalid compress mask dimNum, expect: " << maskDim
1342	                               << ", but got: " << actualMaskDim;
1343	                return ERROR_INVALID_TENSOR_SIZE;
1344	            }
1345	            const auto &dims = inTensorDescs.at(maskId_).shape.dims;
1346	            // 310P legacy: [1, 8, 128, 16]; 310P long window: [1, 128, 2048, 16]
1347	            const bool legacy128 = (dims[0] == 1 && dims[1] == COMPRESS_MASK_SIZE / BYTE2_ALIGN &&
1348	                                    dims[2] == COMPRESS_MASK_SIZE && dims[3] == BYTE2_ALIGN);
1349	            const bool long2048 = (dims[0] == 1 && dims[1] == LONG_COMPRESS_NZ_DIM1 &&
1350	                                   dims[2] == LONG_COMPRESS_LEN && dims[3] == BYTE2_ALIGN);
1351	            if (!legacy128 && !long2048) {
1352	                ATB_LOG(ERROR) << GetLogPrefix() << "invalid compress mask shape, expect [1,8,128,16] or [1,"
1353	                               << LONG_COMPRESS_NZ_DIM1 << "," << LONG_COMPRESS_LEN << ",16]";
1354	                return ERROR_INVALID_TENSOR_DIM;
1355	            }
1356	            if (long2048) {
1357	                if (!GetSingleton<Config>().Is310P()) {
1358	                    ATB_LOG(ERROR) << GetLogPrefix()
1359	                                   << "MASK_TYPE_NORM_COMPRESS long mask [1,128,2048,16] only supports "
1360	                                      "Atlas 300I Duo inference product";
1361	                    return ERROR_INVALID_PARAM;
1362	                }
1363	                if (inTensorDescs.at(maskId_).dtype != ACL_FLOAT16) {
1364	                    ATB_LOG(ERROR) << GetLogPrefix() << "MASK_TYPE_NORM_COMPRESS long mask requires fp16 mask dtype";
1365	                    return ERROR_INVALID_TENSOR_DTYPE;
1366	                }
1367	                if (param_.scaleType != infer::SelfAttentionParam::SCALE_TYPE_TOR) {
1368	                    ATB_LOG(ERROR) << GetLogPrefix() 
1369	                                   << "MASK_TYPE_NORM_COMPRESS long 2048 mask only supports SCALE_TYPE_TOR";
1370	                    return ERROR_INVALID_PARAM;
1371	                }
1372	            }
1373	        } else if (maskFormat == ACL_FORMAT_ND) {
1374	            // 910b, 950
1375	            // maskDim = 2: [128,128]
1376	            if (actualMaskDim != maskDim) {
1377	                ATB_LOG(ERROR) << GetLogPrefix() << "invalid compress mask dimNum, expect: " << maskDim
1378	                               << ", but got: " << actualMaskDim;
1379	                return ERROR_INVALID_TENSOR_SIZE;
1380	            }
1381	            int64_t maxMaskLen = COMPRESS_MASK_SIZE;
1382	            if (Mki::PlatformInfo::Instance().GetPlatformType() == Mki::PlatformType::ASCEND_950) {
1383	                maxMaskLen = COMPRESS_MASK_SIZE_950;
1384	            }
1385	            if (inTensorDescs.at(maskId_).shape.dims[0] != maxMaskLen || // 128 : compress mask shape
1386	                inTensorDescs.at(maskId_).shape.dims[1] != maxMaskLen) { // 128 : compress mask shape
1387	                ATB_LOG(ERROR) << GetLogPrefix() << "invalid compress mask shape, expect[" << maxMaskLen << ", "
1388	                               << "], but got: [" << inTensorDescs.at(maskId_).shape.dims[0] << ", "
1389	                               << inTensorDescs.at(maskId_).shape.dims[1] << "].";
1390	                return ERROR_INVALID_TENSOR_DIM;
1391	            }
1392	        }
1393	    } else if (param_.maskType == infer::SelfAttentionParam::MaskType::MASK_TYPE_NORM) {
1394	        // norm mask: [maxseqlen, maxseqlen], [batch, maxseqlen, maxseqlen]
1395	        if (actualMaskDim == 3) { // 3: maskDim with batch, need to check batch compare to seqlen
1396	            // mask: [batch, maxseqlen, maxseqlen]
1397	            // seqlen shape: one of [2, batch], [batch], lastDim is batch
1398	            int64_t seqLenDimNum = inTensorDescs.at(tokenOffsetId_).shape.dimNum;
1399	            int64_t seqlenBatch = inTensorDescs.at(tokenOffsetId_).shape.dims[seqLenDimNum - 1];
1400	            if (inTensorDescs.at(maskId_).shape.dims[0] != seqlenBatch) {
1401	                ATB_LOG(ERROR) << GetLogPrefix() << "invalid compress mask batch("
1402	                               << inTensorDescs.at(maskId_).shape.dims[0]
1403	                               << ") expect to be the same as seqlen batch: " << seqlenBatch;
1404	                return ERROR_INVALID_TENSOR_SIZE;
1405	            }
1406	        }
1407	    }
1408	    return NO_ERROR;
1409	}
1410	
1411	Status SelfAttentionOperation::PAMaskDimCheck(const SVector<TensorDesc> &inTensorDescs) const
1412	{
1413	    if (hasSlopes_) {
1414	        if (inTensorDescs.at(maskId_).dtype == aclDataType::ACL_FLOAT16 &&
1415	            param_.kernelType == infer::SelfAttentionParam::KERNELTYPE_DEFAULT) {
1416	            ATB_LOG(ERROR) << "kernelType should be KERNELTYPE_HIGH_PRECISION"
1417	                           << "when using alibi compress mask with float16";
1418	            return ERROR_INVALID_PARAM;
1419	        }
1420	        if (inTensorDescs.at(maskId_).shape.dimNum == 2 &&      // 2: [256,256]
1421	            (inTensorDescs.at(maskId_).shape.dims[0] != 256 ||  // 256 : compress mask shape
1422	             inTensorDescs.at(maskId_).shape.dims[1] != 256)) { // 256 : compress mask shape
1423	            ATB_LOG(ERROR) << "invalid alibi compress mask shape, should be [256, 256]";
1424	            return ERROR_INVALID_TENSOR_DIM;
1425	        } else if (inTensorDescs.at(maskId_).shape.dimNum == 3) { // 3: [head_num, seqlen, 128]
1426	            if (param_.maskType == infer::SelfAttentionParam::MASK_TYPE_ALIBI_COMPRESS_LEFT_ALIGN) {
1427	                ATB_LOG(ERROR) << " shape of left align alibi compress mask should be [256, 256]";
1428	                return ERROR_INVALID_TENSOR_DIM;
1429	            }
1430	            if (inTensorDescs.at(maskId_).shape.dims[0] != param_.headNum &&
1431	                inTensorDescs.at(maskId_).shape.dims[2] != 128) { // 2: last dim 128 : compress mask shape
1432	                ATB_LOG(ERROR) << "invalid alibi compress mask shape, should be [head_num, seqlen, 128]";
1433	                return ERROR_INVALID_TENSOR_DIM;
1434	            }
1435	        } else if (inTensorDescs.at(maskId_).shape.dimNum == 4) { // 4: wrong mask dimnum
1436	            ATB_LOG(ERROR) << "invalid alibi compress mask dimNum";
1437	            return ERROR_INVALID_TENSOR_SIZE;
1438	        }
1439	    } else if (param_.maskType == infer::SelfAttentionParam::MASK_TYPE_NORM_COMPRESS) {
1440	        return NormMaskDimCheck(inTensorDescs);
1441	    } else {
1442	        if (inTensorDescs.at(maskId_).shape.dimNum != 2 && // 5: attnMask 2: 2 dims
1443	            inTensorDescs.at(maskId_).shape.dimNum != 3 && // 5: attnMask 3: 3 dims
1444	            inTensorDescs.at(maskId_).shape.dimNum != 4) { // 5: attnMask 4: 4 dims
1445	            ATB_LOG(ERROR) << "invalid mask dimNum";
1446	            return ERROR_INVALID_TENSOR_SIZE;
1447	        }
1448	    }
1449	    return NO_ERROR;
1450	}
1451	
1452	Status SelfAttentionOperation::PAMaskDimCheckNz(const SVector<TensorDesc> &inTensorDescs) const
1453	{
1454	    if (hasSlopes_) {
1455	        if (inTensorDescs.at(maskId_).shape.dimNum != 4) { // 4: [head_num,128//16,maxSeqlen,16] or [1,256//16,256,16]
1456	            ATB_LOG(ERROR) << GetLogPrefix() << "invalid mask dimNum";
1457	            return ERROR_INVALID_TENSOR_SIZE;
1458	        } else if (inTensorDescs.at(maskId_).shape.dimNum == 4 &&   // 4: compress mask dimNum
1459	                   inTensorDescs.at(maskId_).shape.dims[3] != 16) { // 3: dim3 16: nz format
1460	            ATB_LOG(ERROR) << GetLogPrefix() << "invalid alibi compress mask shape";
1461	            return ERROR_INVALID_TENSOR_DIM;
1462	        }
1463	    } else if (param_.maskType == infer::SelfAttentionParam::MASK_TYPE_NORM_COMPRESS) {
1464	        return NormMaskDimCheck(inTensorDescs);
1465	    }
1466	    return NO_ERROR;
1467	}
1468	
1469	Status SelfAttentionOperation::SWAMaskDimCheck(const SVector<TensorDesc> &inTensorDescs) const
1470	{
1471	    if (param_.calcType == infer::SelfAttentionParam::DECODER) { // decoder无mask
1472	        return NO_ERROR;
1473	    }
1474	    uint32_t maskId = 5; // 5: mask
1475	    if (param_.kvcacheCfg == atb::infer::SelfAttentionParam::K_BYPASS_V_BYPASS ||
1476	        param_.calcType == infer::SelfAttentionParam::PA_ENCODER) {
1477	        maskId -= 2; // 2: key,value 不传
1478	    }
1479	    if (isMla_) {
1480	        maskId = 2;
1481	    }
1482	    if (GetSingleton<Config>().Is910B()) {
1483	        if (inTensorDescs.at(maskId).shape.dimNum != 2) { // 2: mask dimNum
1484	            ATB_LOG(ERROR) << "dimNum of swa mask should be two";
1485	            return ERROR_INVALID_TENSOR_DIM;
1486	        }
1487	        if (param_.maskType == infer::SelfAttentionParam::MASK_TYPE_SLIDING_WINDOW_COMPRESS) {
1488	            if (inTensorDescs.at(maskId).shape.dims[0] != 512 || // 512: swa compress mask shape
1489	                inTensorDescs.at(maskId).shape.dims[1] != 512) { // 512: swa compress mask shape
1490	                ATB_LOG(ERROR) << "shape of swa compress mask should be [512,512]";
1491	                return ERROR_INVALID_TENSOR_DIM;
1492	            }
1493	        }
1494	    } else {
1495	        if (inTensorDescs.at(maskId).shape.dimNum != 4) { // 4: mask dimNum 310p
1496	            ATB_LOG(ERROR) << "dimNum of swa mask should be four";
1497	            return ERROR_INVALID_TENSOR_DIM;
1498	        }
1499	        if (param_.maskType == infer::SelfAttentionParam::MASK_TYPE_SLIDING_WINDOW_COMPRESS) {
1500	            if (inTensorDescs.at(maskId).shape.dims[0] != 1 ||   // [1, 32, 512, 16]: swa compress mask shape
1501	                inTensorDescs.at(maskId).shape.dims[1] != 32 ||  // [1, 32, 512, 16]: swa compress mask shape
1502	                inTensorDescs.at(maskId).shape.dims[2] != 512 || // [1, 32, 512, 16]: swa compress mask shape
1503	                inTensorDescs.at(maskId).shape.dims[3] != 16) {  // [1, 32, 512, 16]: swa compress mask shape
1504	                ATB_LOG(ERROR) << "shape of swa compress mask should be [1, 32, 512, 16]";
1505	                return ERROR_INVALID_TENSOR_DIM;
1506	            }
1507	        }
1508	    }
1509	    return NO_ERROR;
1510	}

