63	{
64	    ATB_LOG(INFO) << GetLogPrefix() << "SelfAttentionAclnnRunner::BuildAclnnVariantPack, runnerVariantPack: "
65	                  << runnerVariantPack.ToString();
66	
67	    atbVariantPack_ = runnerVariantPack;
68	    InitTensorIndex();
69	    size_t seqLenIndex = 0;
70	    if (param_.maskType != infer::SelfAttentionParam::MASK_TYPE_UNDEFINED) {
71	        seqLenIndex = 4;
72	    } else {
73	        seqLenIndex = 3;
74	    }
75	    batch_ = atbVariantPack_.inTensors.at(seqLenIndex)
76	                 .desc.shape.dims[atbVariantPack_.inTensors.at(seqLenIndex).desc.shape.dimNum - 1];
77	    aclnnVariantPack_.aclInTensors.reserve(aclInTensorNum_);
78	    aclnnVariantPack_.aclInTensors.resize(aclInTensorNum_);
79	    aclnnVariantPack_.aclInTensorList.reserve(aclInTensorListNum_);
80	    aclnnVariantPack_.aclInTensorList.resize(aclInTensorListNum_);
81	    Status st = CreateQueryAclnnTensor();
82	    if (st != NO_ERROR) {
83	        return st;
84	    }
85	    st = CreateKeyAclnnTensorList();
86	    if (st != NO_ERROR) {
87	        return st;
88	    }
89	    st = CreateValueAclnnTensorList();
90	    if (st != NO_ERROR) {
91	        return st;
92	    }
93	    if (!isDecoder_) {
94	        // Prefill need mask
95	        switch (param_.maskType) {
96	            case infer::SelfAttentionParam::MASK_TYPE_ALIBI:
97	                st = CreatePseShiftAclnnTensor();
98	                if (st != NO_ERROR) {
99	                    return st;
100	                }
101	                break;
102	            case infer::SelfAttentionParam::MASK_TYPE_NORM:
103	            case infer::SelfAttentionParam::MASK_TYPE_NORM_COMPRESS:
104	                st = CreateAttenMaskAclnnTensor();
105	                if (st != NO_ERROR) {
106	                    return st;
107	                }
108	                break;
109	            default:
110	                break;
111	        }
112	    } else if (param_.maskType != infer::SelfAttentionParam::MASK_TYPE_UNDEFINED) {
113	        atbInTensorIndex_++;
114	    }
115	    st = CreateActualSeqLengthsAclIntArray();
116	    if (st != NO_ERROR) {
117	        return st;
118	    }
119	
120	    aclnnVariantPack_.aclOutTensors.reserve(aclOutTensorNum_);
121	    aclnnVariantPack_.aclOutTensors.resize(aclOutTensorNum_);
122	    aclnnVariantPack_.aclOutTensorList.reserve(aclOutTensorListNum_);
123	    aclnnVariantPack_.aclOutTensorList.resize(aclOutTensorListNum_);
124	    return CreateAttentionOutAclnnTensor();
125	}
