130	
131	    aclTensor *query = aclnnVariantPack_.aclInTensors.at(queryAclTensorIndex_)->tensor;
132	    aclTensorList *key = aclnnVariantPack_.aclInTensorList.at(keyAclTensorListIndex_);
133	    aclTensorList *value = aclnnVariantPack_.aclInTensorList.at(valueAclTensorListIndex_);
134	    aclTensor *pseShift = nullptr;
135	    aclTensor *attenMask = nullptr;
136	    if (!isDecoder_) {
137	        if (param_.maskType == infer::SelfAttentionParam::MASK_TYPE_ALIBI) {
138	            pseShift = aclnnVariantPack_.aclInTensors.at(pseShiftAclTensorIndex_)->tensor;
139	        }
140	        if (param_.maskType == infer::SelfAttentionParam::MASK_TYPE_NORM ||
141	            param_.maskType == infer::SelfAttentionParam::MASK_TYPE_NORM_COMPRESS) {
142	            attenMask = aclnnVariantPack_.aclInTensors.at(attenMaskAclTensorIndex_)->tensor;
143	        }
144	    }
145	
146	    aclTensor *attentionOut = aclnnVariantPack_.aclOutTensors.at(attentionOutAclTensorIndex_)->tensor;
147	
148	    std::string inputLayoutStr = aclnnParam_.inputLayoutStr;
149	    auto inputLayout = std::make_unique<char[]>(inputLayoutStr.length() + 1);
150	    errno_t err = strcpy_s(inputLayout.get(), inputLayoutStr.length() + 1, inputLayoutStr.c_str());
151	    if (err != 0) {
152	        ATB_LOG(ERROR) << GetLogPrefix() << "inputLayout strcpy_s failed";
153	        return ERROR_INVALID_PARAM;
154	    }
155	    aclOpExecutor *rawExecutePtr = aclnnExecutor_.get();
156	
157	    aclnnStatus ret = aclnnFusedInferAttentionScoreV5GetWorkspaceSizeFunc_(
158	        query, key, value, pseShift, attenMask, actualSeqLengths_,
159	        actualSeqLengths_, // actualSeqLengthsKv
160	        nullptr,           // deqScale1
161	        nullptr,           // quantScale1
162	        nullptr,           // deqScale2
163	        nullptr,           // quantScale2
164	        nullptr,           // quantOffset2
165	        nullptr,           // antiquantScale
166	        nullptr,           // antiquantOffset
167	        nullptr,           // blockTable
168	        nullptr,           // queryPaddingSize
169	        nullptr,           // kvPaddingSize
170	        nullptr,           // keyAntiquantScale
171	        nullptr,           // keyAntiquantOffset
172	        nullptr,           // valueAntiquantScale
173	        nullptr,           // valueAntiquantOffset
174	        nullptr,           // keySharedPrefix
175	        nullptr,           // valueSharedPrefix
176	        nullptr,           // actualSharedPrefixLen
177	        nullptr,           // queryRope
178	        nullptr,           // keyRope
179	        nullptr,           // keyRopeAntiquantScale
180	        nullptr,           // dequantScaleQuery
181	        nullptr,           // learnableSink
182	        nullptr,           // qStartIdx
183	        nullptr,           // kvStartIdx
184	        aclnnParam_.numHeads, aclnnParam_.scaleValue, aclnnParam_.preTokens, aclnnParam_.nextTokens, inputLayout.get(),
185	        aclnnParam_.numKeyValueHeads, aclnnParam_.sparseMode, aclnnParam_.innerPrecise, aclnnParam_.blockSize,
186	        aclnnParam_.antiquantMode, aclnnParam_.softmaxLseFlag, aclnnParam_.keyAntiquantMode,
187	        aclnnParam_.valueAntiquantMode, aclnnParam_.queryQuantMode, aclnnParam_.pseType, attentionOut,
188	        nullptr, // softmaxLse
189	        &(atbVariantPack_.workspaceBufferSize), &rawExecutePtr);
190	    aclnnExecutor_ = std::shared_ptr<aclOpExecutor>(rawExecutePtr, [this](aclOpExecutor *ptr) {
191	        if (ptr && executorRepeatable_) {
192	            aclDestroyAclOpExecutor(ptr);
193	        }
194	    });
195	    if (ret == ACL_SUCCESS) {
196	        ATB_LOG(INFO) << GetLogPrefix() << "workspaceSize: " << atbVariantPack_.workspaceBufferSize;
197	    } else {
198	        ATB_LOG(ERROR) << GetLogPrefix() << "SetAclNNWorkspaceExecutor failed, ret: " << ret;
199	    }
200	    return ret;
