271	Status SelfAttentionAclnnRunner::CreateQueryAclnnTensor()
272	{
273	    ATB_LOG(INFO) << "SelfAttentionAclnnRunner::CreateQueryAclnnTensor";
274	
275	    Tensor atbTensor = atbVariantPack_.inTensors.at(atbInTensorIndex_++);
276	    std::shared_ptr<AclNNTensor> aclnnTensorPtr = InitAclnnTensor(atbTensor, QUERY_ACLNN_TENSOR_IDX);
277	    Dims storageShape = atbTensor.desc.shape;
278	    // [B*S, N, D] reduced to [B*1, N, D]
279	    isDecoder_ = storageShape.dims[0] == batch_;
280	    Dims viewShape;
281	    if (param_.maskType == infer::SelfAttentionParam::MASK_TYPE_ALIBI) {
282	        viewShape.dimNum = 4;  // 4: [B, S, N, D]
283	        viewShape.dims[0] = batch_;
284	        viewShape.dims[1] = storageShape.dims[0] / batch_;
285	        viewShape.dims[2] = param_.headNum;
286	        if (storageShape.dimNum == 2) {
287	            viewShape.dims[3] = storageShape.dims[1] / param_.headNum;
288	        } else if (storageShape.dimNum == 3) {
289	            viewShape.dims[3] = storageShape.dims[2];  // 3: D(head_size); 2: head_size
290	        }
291	        aclnnParam_.inputLayoutStr = "BSND";
292	    } else {
293	        viewShape.dimNum = storageShape.dimNum;
294	        for (uint64_t i = 0; i < viewShape.dimNum; i++) {
295	            viewShape.dims[i] = storageShape.dims[i];
296	        }
297	    }
298	    aclnnTensorPtr->strides = GetCopyTensorStride(viewShape);
299	    aclnnTensorPtr->tensor = aclCreateTensor(viewShape.dims,
300	        viewShape.dimNum,
301	        atbTensor.desc.dtype,
302	        aclnnTensorPtr->strides.data(),
303	        0,
304	        atbTensor.desc.format,
305	        storageShape.dims,
306	        storageShape.dimNum,
307	        atbTensor.deviceData);
308	    if (!aclnnTensorPtr->tensor) {
309	        ATB_LOG(ERROR) << GetLogPrefix() << "query aclCreateTensor failed";
310	        return ERROR_INTERNAL_ERROR;
311	    }
312	    aclnnVariantPack_.aclInTensors.at(aclInTensorIndex_) = aclnnTensorPtr;
313	    queryAclTensorIndex_ = aclInTensorIndex_++;
314	    return NO_ERROR;
315	}
