329	        if (storageShape.dimNum == 2) {
330	            viewShape.dims[3] = storageShape.dims[1] / param_.kvHeadNum;
331	        } else if (storageShape.dimNum == 3) {
332	            viewShape.dims[3] = storageShape.dims[2];  // 3: D(head_size); 2: head_size
333	        }
334	    } else {
335	        viewShape.dimNum = storageShape.dimNum;
336	        for (uint64_t i = 0; i < viewShape.dimNum; i++) {
337	            viewShape.dims[i] = storageShape.dims[i];
338	        }
339	    }
