341	    aclnnTensorPtr->tensor = aclCreateTensor(viewShape.dims,
342	        viewShape.dimNum,
343	        atbTensor.desc.dtype,
344	        aclnnTensorPtr->strides.data(),
345	        0,
346	        atbTensor.desc.format,
347	        storageShape.dims,
348	        storageShape.dimNum,
349	        atbTensor.deviceData);
350	    if (!aclnnTensorPtr->tensor) {
351	        ATB_LOG(ERROR) << GetLogPrefix() << "key aclCreateTensor failed";
