367	Status SelfAttentionAclnnRunner::CreateValueAclnnTensorList()
368	{
369	    ATB_LOG(INFO) << "SelfAttentionAclnnRunner::CreateValueAclnnTensorList";
370	    Tensor atbTensor = atbVariantPack_.inTensors.at(atbInTensorIndex_++);
371	    std::shared_ptr<AclNNTensor> aclnnTensorPtr = InitAclnnTensor(atbTensor, VALUE_ACLNN_TENSOR_IDX);
372	    Dims storageShape = atbTensor.desc.shape;
373	    Dims viewShape;
374	    if (param_.maskType == infer::SelfAttentionParam::MASK_TYPE_ALIBI) {
375	        viewShape.dimNum = 4;  // 4: [B, S, N, D]
376	        viewShape.dims[0] = batch_;
377	        viewShape.dims[1] = storageShape.dims[0] / batch_;
378	        viewShape.dims[2] = param_.kvHeadNum;
379	        if (storageShape.dimNum == 2) {
380	            viewShape.dims[3] = storageShape.dims[1] / param_.kvHeadNum;
381	        } else if (storageShape.dimNum == 3) {
382	            viewShape.dims[3] = storageShape.dims[2];  // 3: D(head_size); 2: head_size
383	        }
384	    } else {
385	        viewShape.dimNum = storageShape.dimNum;
386	        for (uint64_t i = 0; i < viewShape.dimNum; i++) {
387	            viewShape.dims[i] = storageShape.dims[i];
388	        }
389	    }
390	    aclnnTensorPtr->strides = GetCopyTensorStride(viewShape);
391	    aclnnTensorPtr->tensor = aclCreateTensor(viewShape.dims,
392	        viewShape.dimNum,
393	        atbTensor.desc.dtype,
394	        aclnnTensorPtr->strides.data(),
395	        0,
396	        atbTensor.desc.format,
397	        storageShape.dims,
398	        storageShape.dimNum,
399	        atbTensor.deviceData);
400	    if (!aclnnTensorPtr->tensor) {
401	        ATB_LOG(ERROR) << GetLogPrefix() << "value aclCreateTensor failed";
402	        return ERROR_INTERNAL_ERROR;
403	    }
404	    aclnnVariantPack_.aclInTensors.at(aclInTensorIndex_) = aclnnTensorPtr;
405	    aclTensor *valueTensors[1] = {aclnnTensorPtr->tensor};
406	    auto valueTensorList = aclCreateTensorList(valueTensors, 1);
407	    if (valueTensorList) {
408	        aclnnVariantPack_.aclInTensorList.at(aclInTensorListIndex_) = valueTensorList;
409	        valueAclTensorListIndex_ = aclInTensorListIndex_++;
410	        aclInTensorIndex_++;
411	        return NO_ERROR;
412	    }
413	    ATB_LOG(ERROR) << GetLogPrefix() << "value aclCreateTensorList failed";
414	    return ERROR_INTERNAL_ERROR;
415	}
416	
417	Status SelfAttentionAclnnRunner::CreatePseShiftAclnnTensor()
418	{
419	    ATB_LOG(INFO) << "SelfAttentionAclnnRunner::CreatePseShiftAclnnTensor";
420	    Tensor atbTensor = atbVariantPack_.inTensors.at(atbInTensorIndex_++);
421	    std::shared_ptr<AclNNTensor> aclnnTensorPtr = InitAclnnTensor(atbTensor, PSE_SHIFT_ACLNN_TENSOR_IDX);
422	    Dims storageShape = atbTensor.desc.shape;
423	    Dims viewShape;
424	    viewShape.dimNum = 4;  // 4: [batch, headNum, maxSeqLen, maxSeqLen]
425	    if (storageShape.dimNum == 4) {
426	        viewShape.dims[0] = storageShape.dims[0];
427	        viewShape.dims[1] = storageShape.dims[1];
428	        viewShape.dims[2] = storageShape.dims[2];  // 2: maxSeqLen
429	        viewShape.dims[3] = storageShape.dims[3];  // 3: maxSeqLen
430	    }
431	    if (storageShape.dimNum == 3) {
432	        viewShape.dims[0] = 1;
433	        viewShape.dims[1] = storageShape.dims[0];
434	        viewShape.dims[2] = storageShape.dims[1];  // 2: maxSeqLen
435	        viewShape.dims[3] = storageShape.dims[2];  // 3: maxSeqLen
436	    }
437	    aclnnTensorPtr->strides = GetCopyTensorStride(viewShape);
438	    aclnnTensorPtr->tensor = aclCreateTensor(viewShape.dims,
439	        viewShape.dimNum,
440	        atbTensor.desc.dtype,
441	        aclnnTensorPtr->strides.data(),
442	        0,
443	        atbTensor.desc.format,
444	        storageShape.dims,
445	        storageShape.dimNum,
446	        atbTensor.deviceData);
447	    if (!aclnnTensorPtr->tensor) {
448	        ATB_LOG(ERROR) << GetLogPrefix() << "pseShift aclCreateTensor failed";
449	        return ERROR_INTERNAL_ERROR;
450	    }
451	    aclnnVariantPack_.aclInTensors.at(aclInTensorIndex_) = aclnnTensorPtr;
452	    pseShiftAclTensorIndex_ = aclInTensorIndex_++;
453	    return NO_ERROR;
454	}
455	
456	Status SelfAttentionAclnnRunner::CreateAttenMaskAclnnTensor()
457	{
458	    ATB_LOG(INFO) << "SelfAttentionAclnnRunner::CreateAttenMaskAclnnTensor";
459	    Tensor atbTensor = atbVariantPack_.inTensors.at(atbInTensorIndex_++);
460	    std::shared_ptr<AclNNTensor> aclnnTensorPtr = InitAclnnTensor(atbTensor, ATTEN_MASK_ACLNN_TENSOR_IDX);
461	    Dims storageShape = atbTensor.desc.shape;
462	    // only prefill need mask
463	    if (!isDecoder_ && storageShape.dims[1] == 2048 && param_.isTriuMask) {
464	        aclnnParam_.sparseMode = 2;  // 2: leftUpCausal mask
465	    } else if (storageShape.dimNum == 2) { // 2: [maxQSeqlen, maxKVSeqlen]
466	        storageShape.dimNum = 3; // 3: [1, maxQSeqlen, maxKVSeqlen]
467	        for (int64_t i = storageShape.dimNum; i > 0; --i) {
468	            storageShape.dims[i] = storageShape.dims[i-1];
469	        }
470	        storageShape.dims[0] = 1;
471	    }
472	    aclnnTensorPtr->strides = GetCopyTensorStride(storageShape);
473	    aclnnTensorPtr->tensor = aclCreateTensor(storageShape.dims,
474	        storageShape.dimNum,
475	        atbTensor.desc.dtype,
476	        aclnnTensorPtr->strides.data(),
477	        0,
478	        atbTensor.desc.format,
479	        storageShape.dims,
480	        storageShape.dimNum,
481	        atbTensor.deviceData);
482	    if (!aclnnTensorPtr->tensor) {
483	        ATB_LOG(ERROR) << GetLogPrefix() << "attenMask aclCreateTensor failed";
484	        return ERROR_INTERNAL_ERROR;
485	    }
486	    aclnnVariantPack_.aclInTensors.at(aclInTensorIndex_) = aclnnTensorPtr;
487	    attenMaskAclTensorIndex_ = aclInTensorIndex_++;
488	    return NO_ERROR;
489	}
490	
491	Status SelfAttentionAclnnRunner::CreateActualSeqLengthsAclIntArray()
492	{
493	    ATB_LOG(INFO) << "SelfAttentionAclnnRunner::CreateActualSeqLengthsAclIntArray";
494	    Tensor atbTensor = atbVariantPack_.inTensors.at(atbInTensorIndex_++);
495	    if (atbTensor.hostData == nullptr) {
496	        ATB_LOG(ERROR) << "contextLen tensor host data is null";
497	        return ERROR_INVALID_TENSOR_ADDR;
498	    }
499	    if (actualSeqLengths_) {
500	        aclnnStatus ret = aclDestroyIntArray(actualSeqLengths_);
501	        if (ret != ACL_SUCCESS) {
502	            ATB_LOG(ERROR) << GetLogPrefix() << "actualSeqLengths aclDestroyIntArray failed";
503	            return ERROR_INTERNAL_ERROR;
504	        }
505	        actualSeqLengths_ = nullptr;
506	    }
507	    std::vector<int32_t> contextLensInt32;
508	    uint64_t dataSize = atbTensor.dataSize / 4;  // 4: int32 size
509	    contextLensInt32.reserve(dataSize);
510	    contextLensInt32.resize(dataSize);
511	    if (memcpy_s(contextLensInt32.data(), atbTensor.dataSize, atbTensor.hostData, atbTensor.dataSize) != 0) {
512	        ATB_LOG(ERROR) << GetLogPrefix() << "contextLens memcpy_s failed";
513	        return ERROR_INTERNAL_ERROR;
514	    }
515	    std::vector<int64_t> contextLensInt64;
516	    contextLensInt64.reserve(dataSize);
517	    contextLensInt64.resize(dataSize);
518	    contextLensInt64.at(0) = static_cast<int64_t>(contextLensInt32.at(0));
519	    for (uint64_t i = 1; i < dataSize; i++) {
520	        if (aclnnParam_.inputLayoutStr == "TND") {
521	            contextLensInt64.at(i) = static_cast<int64_t>(contextLensInt32.at(i)) + contextLensInt64.at(i - 1);
522	        } else {
523	            contextLensInt64.at(i) = static_cast<int64_t>(contextLensInt32.at(i));
524	        }
525	    }
526	    actualSeqLengths_ = aclCreateIntArray(contextLensInt64.data(), dataSize);
527	    if (actualSeqLengths_) {
528	        return NO_ERROR;
529	    }
530	    ATB_LOG(ERROR) << "actualSeqLengths_ aclCreateIntArray failed!";
531	    return ERROR_INTERNAL_ERROR;
532	}
533	
534	Status SelfAttentionAclnnRunner::CreateAttentionOutAclnnTensor()
535	{
536	    ATB_LOG(INFO) << "SelfAttentionAclnnRunner::CreateAttentionOutAclnnTensor";
537	    Tensor atbTensor = atbVariantPack_.outTensors.at(atbOutTensorIndex_++);
538	    std::shared_ptr<AclNNTensor> aclnnTensorPtr = InitAclnnTensor(atbTensor, ATTENTION_OUT_ACLNN_TENSOR_IDX);
539	    Dims storageShape = atbTensor.desc.shape;
540	    Dims viewShape;
541	    if (param_.maskType == infer::SelfAttentionParam::MASK_TYPE_ALIBI) {
542	        viewShape.dimNum = 4;  // 4: [B, S, N, D]
543	        viewShape.dims[0] = batch_;
544	        viewShape.dims[1] = storageShape.dims[0] / batch_;
545	        viewShape.dims[2] = param_.headNum;
546	        if (storageShape.dimNum == 2) {
547	            viewShape.dims[3] = storageShape.dims[1] / param_.headNum;
548	        } else if (storageShape.dimNum == 3) {
549	            viewShape.dims[3] = storageShape.dims[2];  // 3: D(head_size); 2: head_size
550	        }
551	    } else {
552	        viewShape.dimNum = storageShape.dimNum;
553	        for (uint64_t i = 0; i < viewShape.dimNum; i++) {
554	            viewShape.dims[i] = storageShape.dims[i];
555	        }
556	    }
557	    aclnnTensorPtr->strides = GetCopyTensorStride(viewShape);
558	    aclnnTensorPtr->tensor = aclCreateTensor(viewShape.dims,
559	        viewShape.dimNum,
560	        atbTensor.desc.dtype,
561	        aclnnTensorPtr->strides.data(),
562	        0,
563	        atbTensor.desc.format,
564	        storageShape.dims,
565	        storageShape.dimNum,
566	        atbTensor.deviceData);
567	    if (!aclnnTensorPtr->tensor) {
568	        ATB_LOG(ERROR) << GetLogPrefix() << "attentionOut aclCreateTensor failed";
569	        return ERROR_INTERNAL_ERROR;
570	    }
571	    aclnnVariantPack_.aclOutTensors.at(aclOutTensorIndex_) = aclnnTensorPtr;
572	    attentionOutAclTensorIndex_ = aclOutTensorIndex_++;
573	    return NO_ERROR;
574	}
575	
576	std::shared_ptr<AclNNTensor> SelfAttentionAclnnRunner::InitAclnnTensor(Tensor atbTensor, int aclnnTensorIndex)
577	{
578	    std::shared_ptr<AclNNTensor> aclnnTensorPtr = std::make_shared<AclNNTensor>();
579	    aclnnTensorPtr->atbTensor = atbTensor;
