1779	Status SelfAttentionOperation::InferShapeHiddenSizeCheck(const SVector<TensorDesc> &inTensorDescs) const
1780	{
1781	    int64_t hiddenSizeK = 0;
1782	    int64_t hiddenSizeV = 0;
1783	    int64_t hiddenSizeKcacahe = 0;
1784	    int64_t hiddenSizeVcacahe = 0;
1785	    if (inTensorDescs.at(1).shape.dimNum == 4) {          // 4: 4 dims
1786	        hiddenSizeK = inTensorDescs.at(1).shape.dims[2] * // 1: k 2: 2nd dim
1787	                      inTensorDescs.at(1).shape.dims[3];  // 1: k 3: 3rd dim
1788	    } else {
1789	        hiddenSizeK = inTensorDescs.at(1).shape.dims[1]; // 1: k 1: 1st dim
1790	    }
1791	    if (inTensorDescs.at(2).shape.dimNum == 4) {          // 2: cacheV 4: 4 dims
1792	        hiddenSizeV = inTensorDescs.at(2).shape.dims[2] * // 2: v 2: 2nd dim
1793	                      inTensorDescs.at(2).shape.dims[3];  // 2: v 3: 3rd dim
1794	    } else {
1795	        hiddenSizeV = inTensorDescs.at(2).shape.dims[1]; // 2: v 1: 1st dim
1796	    }
1797	    if (GetSingleton<Config>().Is910B() ||
1798	        Mki::PlatformInfo::Instance().GetPlatformType() == Mki::PlatformType::ASCEND_950) {
1799	        uint64_t hiddenSizePos = inTensorDescs.at(3).shape.dimNum - 1;     // 3: kcache
1800	        hiddenSizeKcacahe = inTensorDescs.at(3).shape.dims[hiddenSizePos]; // 3: kcache 3: khiddenSize
1801	        hiddenSizeVcacahe = inTensorDescs.at(4).shape.dims[hiddenSizePos]; // 4: vcache 3: khiddenSize
1802	    } else {
1803	        hiddenSizeKcacahe = inTensorDescs.at(3).shape.dims[2] * // 3: kcache 2: embedim / 16
1804	                            inTensorDescs.at(3).shape.dims[4];  // 3: kcache 4: 16
1805	        hiddenSizeVcacahe = inTensorDescs.at(4).shape.dims[2] * // 4: vcache 2: embedim / 16
1806	                            inTensorDescs.at(4).shape.dims[4];  // 4: vcache 4: 16
1807	    }
1808	    if (hiddenSizeK != hiddenSizeKcacahe) { // 3: cacheK 3: 3rd dim
1809	        ATB_LOG(ERROR) << "hiddenSize of k should be the same as cacheK";
1810	        return ERROR_INVALID_TENSOR_DIM;
1811	    }
1812	    if (hiddenSizeV != hiddenSizeVcacahe) { // 4: cacheV 3: 3rd dim
1813	        ATB_LOG(ERROR) << "hiddenSize of v should be the same as cacheV";
1814	        return ERROR_INVALID_TENSOR_DIM;
1815	    }
1816	    if (hiddenSizeV % 16 != 0 || hiddenSizeK % 16 != 0) { // 16: kvcache约束 16 ：kvcache约束
1817	        ATB_LOG(ERROR) << "hiddenSize of key and value should be multiples of 16.";
1818	        return ERROR_INVALID_TENSOR_DIM;
1819	    }
1820	    return NO_ERROR;
1821	}
