1880	    if (inTensorDescs.at(tokenOffsetId_).shape.dimNum != 1 ||     // tokenOffset 1: 1dim
1881	        inTensorDescs.at(tokenOffsetId_ + 1).shape.dimNum != 1 || // seqLen 1: 1 dim
1882	        inTensorDescs.at(tokenOffsetId_ + 2).shape.dimNum != 1) { // tokenOffsetId + 2: layerId 1: 1 dim
