2032	Status SelfAttentionOperation::InferShapePrefixDimCheck910B(const SVector<TensorDesc> &inTensorDescs) const
2033	{
2034	    const std::size_t kBlockTablesIndex = 3;
2035	    const std::size_t kSeqLenIndex = param_.maskType != infer::SelfAttentionParam::MASK_TYPE_CAUSAL_MASK ? 5 : 4;
2036	    const std::size_t kBlockSizeIndex = 1;
2037	    const int32_t kMaxHeadSize = 128;
2038	    Status st = InferShapePrefixDimNumCheck910B(inTensorDescs);
2039	    if (st != NO_ERROR) {
2040	        return st;
2041	    }
2042	    if (hasMask_) {
2043	        st = PAMaskDimCheck(inTensorDescs); // check mask
2044	    }
2045	    if (st != NO_ERROR) {
2046	        return st;
2047	    }
2048	    // blockSize * headSize <= kMaxHeadSize ​* kMaxHeadSize
2049	    int32_t blockSize = static_cast<int32_t>(inTensorDescs.at(1).shape.dims[kBlockSizeIndex]);
2050	    uint64_t kvDimNum = inTensorDescs.at(1).shape.dimNum;
2051	    int32_t headSize = static_cast<int32_t>(inTensorDescs.at(1).shape.dims[kvDimNum - 1]);
2052	    if (inTensorDescs.at(1).shape.dimNum == 3) { // dimNum = 3, [numBlocks, blockSize, kvHiddenSize]
2053	        headSize /= kvHeadNum_;                  // kvHiddenSize = headSize * kvHeadNum
2054	    }
2055	    if (headSize > kMaxHeadSize) {
2056	        ATB_LOG(ERROR) << "invalid key, value HeadSize, maximum: " << kMaxHeadSize << ", but got " << headSize;
2057	        return ERROR_INVALID_TENSOR_DIM;
2058	    }
2059	    int32_t qHeadSize = static_cast<int32_t>(inTensorDescs.at(0).shape.dims[inTensorDescs.at(0).shape.dimNum - 1]);
2060	    // dimNum = 2, [batch*qSeqLen, qHiddenSize]
2061	    qHeadSize /= inTensorDescs.at(0).shape.dimNum == 2 ? param_.headNum : 1;
2062	    if (qHeadSize > kMaxHeadSize) {
2063	        ATB_LOG(ERROR) << "invalid query HeadSize, maximum: " << kMaxHeadSize << ", but got " << qHeadSize;
2064	        return ERROR_INVALID_TENSOR_DIM;
2065	    }
2066	    if (qHeadSize % 16 != 0 || headSize % 16 != 0) { // 16: query headSize约束 16: kv headSize约束
2067	        ATB_LOG(ERROR) << "headSize of query, key and value should be multiples of 16";
2068	        return ERROR_INVALID_TENSOR_DIM;
2069	    }
2070	    if (blockSize * headSize > kMaxHeadSize * kMaxHeadSize) {
2071	        ATB_LOG(ERROR) << "invalid blockSize * headSize, maximum: 128 * 128"
2072	                       << ", but got " << blockSize * headSize;
2073	        return ERROR_INVALID_TENSOR_DIM;
2074	    }
2075	    int64_t seqlenBatch = inTensorDescs.at(kSeqLenIndex).shape.dims[0];           // 0: seqLen: [batch]
2076	    int64_t kvSeqLenBatch = inTensorDescs.at(kSeqLenIndex + 1).shape.dims[0];     // 0: kvSeqLen: [batch]
2077	    int64_t blockTablesBatch = inTensorDescs.at(kBlockTablesIndex).shape.dims[0]; // 0: blockTables: [batch, BlockNum]
2078	    if (seqlenBatch != blockTablesBatch || kvSeqLenBatch != blockTablesBatch) {
2079	        ATB_LOG(ERROR) << "invalid seqlenBatch batch size" << seqlenBatch << ", kv: " << kvSeqLenBatch
2080	                       << ", expect: " << blockTablesBatch;
2081	        return ERROR_INVALID_TENSOR_DIM;
2082	    }
2083	    return NO_ERROR;
2084	}
